class Counter extends HTMLElement{constructor(){super(),this._observer=null,this._hasCounted=!1}connectedCallback(){this._targetNumber=parseInt(this.getAttribute("data-count-to"))||0,this.innerHTML="<span>0</span>",this._observer=new IntersectionObserver(t=>{t.forEach(t=>{t.isIntersecting&&!this._hasCounted&&(this._hasCounted=!0,this._startCounting())})},{threshold:.6}),this._observer.observe(this)}_startCounting(){const t=this.querySelector("span"),e=performance.now(),n=s=>{const r=Math.min((s-e)/1500,1),o=Math.floor(r*this._targetNumber);t.textContent=o.toLocaleString(),r<1?requestAnimationFrame(n):t.textContent=this._targetNumber.toLocaleString()};requestAnimationFrame(n)}disconnectedCallback(){this._observer&&this._observer.disconnect()}}customElements.define("count-up",Counter);